// Des: Atomic JSON blob persistence for config files
// Flo: dirzData once > load file or "{}" > save via unique temp + fsync + rename
// I/O: file name + raw JSON body (UI, serve) > blob in ~/.ac-auto-task; load never errors, "{}" on failure
// ===================================================================
const std = @import("std"); const builtin = @import("builtin");
const CF = .{ .maxz = 8 * 1024 * 1024, .empt = "{}", .envw = "USERPROFILE", .envp = "HOME", .bakz = ".bak", .part = ".bak.part", .conf_file = "aa-conf-main.json", .conf_maxz = 64 * 1024, .data_maxz = 64 };
pub const Tune = struct { port: u16 = 4000, workers: u32 = 4, hist_maxz: u32 = 64, tmoz_seco: u32 = 86400, data: []const u8 = ".ac-auto-task" };
pub var tune: Tune = .{}; var data_bufz: [CF.data_maxz]u8 = undefined;
fn confInt(obj: std.json.ObjectMap, key: []const u8, minz: i64, maxz: i64) ?i64 { const valu = obj.get(key) orelse return null; return switch (valu) { .integer => |numb| if (numb >= minz and numb <= maxz) numb else null, else => null }; }
fn dataOkay(name: []const u8) bool { if (name.len == 0 or name.len > CF.data_maxz or std.mem.eql(u8, name, ".") or std.mem.eql(u8, name, "..")) return false; for (name) |byte| { if (!std.ascii.isAlphanumeric(byte) and byte != '.' and byte != '_' and byte != '-') return false; } return true; }
pub fn confApply(allo: std.mem.Allocator, data: []const u8) ?[]const u8 { tune = .{}; const root = std.json.parseFromSliceLeaky(std.json.Value, allo, data, .{}) catch return "aa-conf-main.json is not valid JSON, defaults used"; const obj = switch (root) { .object => |objz| objz, else => return "aa-conf-main.json must be an object, defaults used" }; var badz = false; if (obj.get("port") != null) { if (confInt(obj, "port", 1, 65535)) |numb| tune.port = @intCast(numb) else badz = true; } if (obj.get("jobs_same_time") != null) { if (confInt(obj, "jobs_same_time", 1, 4)) |numb| tune.workers = @intCast(numb) else badz = true; } if (obj.get("cmds_hist_maxz") != null) { if (confInt(obj, "cmds_hist_maxz", 1, 10_000)) |numb| tune.hist_maxz = @intCast(numb) else badz = true; } if (obj.get("time_limi_seco") != null) { if (confInt(obj, "time_limi_seco", 1, 24 * 60 * 60)) |numb| tune.tmoz_seco = @intCast(numb) else badz = true; } if (obj.get("apps_data_loca")) |valu| { if (valu == .string and dataOkay(valu.string)) { @memcpy(data_bufz[0..valu.string.len], valu.string); tune.data = data_bufz[0..valu.string.len]; } else badz = true; } return if (badz) "aa-conf-main.json: a bad value was ignored, its default used" else null; }
pub fn confLoad(allo: std.mem.Allocator, iozz: std.Io, root: []const u8) ?[]const u8 { const path = std.fs.path.join(allo, &.{ root, CF.conf_file }) catch return null; const data = std.Io.Dir.cwd().readFileAlloc(iozz, path, allo, .limited(CF.conf_maxz)) catch return null; return confApply(allo, data); }
pub const MAXZ_BLOB = CF.maxz; pub const HOME_VARZ = if (builtin.os.tag == .windows) CF.envw else CF.envp; const BAKZ_FILE = [_][]const u8{ "config.json", "output.json" };
pub fn enviLive() std.process.Environ { if (builtin.os.tag == .windows) return .{ .block = .global }; return .{ .block = .{ .slice = std.mem.span(std.c.environ) } }; }
var dirz_bufz: [1024]u8 = undefined; var dirz_lenz: std.atomic.Value(usize) = .init(0);
pub fn dirzData(allo: std.mem.Allocator, iozz: std.Io) ![]const u8 { const lenz = dirz_lenz.load(.acquire); if (lenz > 0) return dirz_bufz[0..lenz]; const home = std.process.Environ.getAlloc(enviLive(), allo, HOME_VARZ) catch return error.NoHomeDir; const dirz = try std.fs.path.join(allo, &.{ home, tune.data }); if (dirz.len > dirz_bufz.len) return dirz; std.Io.Dir.cwd().createDirPath(iozz, dirz) catch {}; @memcpy(dirz_bufz[0..dirz.len], dirz); dirz_lenz.store(dirz.len, .release); return dirz_bufz[0..dirz.len]; }
pub fn load(allo: std.mem.Allocator, iozz: std.Io, name: []const u8) []const u8 { const dirz = dirzData(allo, iozz) catch return CF.empt; const path = std.fs.path.join(allo, &.{ dirz, name }) catch return CF.empt; const data = std.Io.Dir.cwd().readFileAlloc(iozz, path, allo, .limited(MAXZ_BLOB)) catch return CF.empt; if (data.len == 0) return CF.empt; return data; }
pub var mute_save: std.Io.Mutex = .init; var temp_sequ: std.atomic.Value(u32) = .init(0);
pub fn save(allo: std.mem.Allocator, iozz: std.Io, name: []const u8, body: []const u8) !void { try mute_save.lock(iozz); defer mute_save.unlock(iozz); return lockSave(allo, iozz, name, body); }
pub fn lockSave(allo: std.mem.Allocator, iozz: std.Io, name: []const u8, body: []const u8) !void { const dirz = try dirzData(allo, iozz); const path = try std.fs.path.join(allo, &.{ dirz, name }); if (std.fs.path.dirname(path)) |pare| std.Io.Dir.cwd().createDirPath(iozz, pare) catch {}; const sequ = temp_sequ.fetchAdd(1, .monotonic); const temp = try std.fmt.allocPrint(allo, "{s}.{d}.tmp", .{ path, sequ }); var file = try std.Io.Dir.cwd().createFile(iozz, temp, .{ .truncate = true, .read = true }); { errdefer file.close(iozz); try file.writePositionalAll(iozz, body, 0); file.sync(iozz) catch {}; } file.close(iozz); for (BAKZ_FILE) |item| if (std.mem.eql(u8, item, name)) { bakzKeep(allo, iozz, path); break; }; try std.Io.Dir.rename(.cwd(), temp, .cwd(), path, iozz); }
fn bakzKeep(allo: std.mem.Allocator, iozz: std.Io, path: []const u8) void { const part = std.fmt.allocPrint(allo, "{s}" ++ CF.part, .{path}) catch return; const bakz = std.fmt.allocPrint(allo, "{s}" ++ CF.bakz, .{path}) catch return; const cwdz = std.Io.Dir.cwd(); cwdz.copyFile(path, cwdz, part, iozz, .{}) catch return; std.Io.Dir.rename(.cwd(), part, .cwd(), bakz, iozz) catch {}; }
